{"command":"python3 << 'EOF'
from PIL import Image
import math, random

def avg(img, box):
    t = img.crop(box).resize((1,1), Image.LANCZOS)
    return t.getpixel((0,0))

frames = []
for fn, cols, rows in [('sbB.jpg',5,5), ('sb_L02_M1.jpg',5,5), ('sb_L02_M2.jpg',5,3)]:
    im = Image.open(fn).convert('RGB')
    W,H = im.size
    tw, th = 160, 90
    for r in range(rows):
        for c in range(cols):
            box = (c*tw, r*th, (c+1)*tw, (r+1)*th)
            if box[2] <= W and box[3] <= H:
                frames.append(avg(im, box))
N = len(frames)
print('frames:', N)

bc = Image.open('barcode.png').convert('RGB')
w,h = bc.size
def bc_avg(x0,x1):
    t = bc.crop((int(x0),0,int(x1),h)).resize((1,1), Image.LANCZOS)
    return t.getpixel((0,0))

def dist(a,b):
    return math.sqrt(sum((a[i]-b[i])**2 for i in range(3)))/math.sqrt(3*255*255)

content_w = 940
bc_full = bc_avg(0, content_w)
vid_full = tuple(sum(f[i] for f in frames)//N for i in range(3))
print('barcode full mean RGB:', bc_full, ' video mean RGB:', vid_full, ' d=%.3f'%dist(bc_full, vid_full))

errs = [dist(bc_avg(i*content_w/N,(i+1)*content_w/N), frames[i]) for i in range(N)]
print('mean aligned distance: %.3f' % (sum(errs)/N))
errs2 = [dist(bc_avg(i*w/N,(i+1)*w/N), frames[i]) for i in range(N)]
print('mean distance (full 1000px): %.3f' % (sum(errs2)/N))
random.seed(1); sh = frames[:]; random.shuffle(sh)
print('shuffled baseline: %.3f' % (sum(dist(bc_avg(i*content_w/N,(i+1)*content_w/N), sh[i]) for i in range(N))/N))

def hexc(c): return '#%02x%02x%02x' % c
for i in list(range(0,20))+list(range(40,50))+list(range(N-14,N)):
    print(f'{i:2d} bc={hexc(bc_avg(i*content_w/N,(i+1)*content_w/N))} vid={hexc(frames[i])}')
EOF"}

